/**
 * The service worker of the site (RF-53, RF-54, RT-40, ADR 0052), generated by Workbox after
 * the build and the search index, so that both are part of what it keeps offline:
 *
 * - precached on the first visit: every page (texts, records, sections), the scripts and
 *   styles, the Pagefind search index and the manifest;
 * - cached when first seen: images (stale-while-revalidate) and fonts (cache-first);
 * - never cached: audio and video, which need a connection, and the admin.
 */
import type { GenerateSWOptions } from 'workbox-build';

/** Most images kept for offline viewing; the oldest are dropped beyond it. */
export const MAX_CACHED_IMAGES = 300;

export function serviceWorkerOptions(siteDir: string): GenerateSWOptions {
  return {
    globDirectory: siteDir,
    swDest: `${siteDir}/sw.js`,
    globPatterns: ['**/*.{html,js,css}', 'pagefind/**/*', 'manifest.webmanifest'],
    globIgnores: ['admin/**', 'audio/**', 'sw.js', 'workbox-*.js'],
    // Pages are folders (/obras/ is /obras/index.html), and client-side navigation fetches
    // them by their folder URL.
    directoryIndex: 'index.html',
    // Pagefind asks for its index with a cache-busting `?ts=<time>`; the precached file is the
    // same whatever the value. The others are Workbox's defaults.
    ignoreURLParametersMatching: [/^utm_/, /^fbclid$/, /^ts$/],
    // The largest Pagefind fragments and pages stay well under this; audio is not matched.
    maximumFileSizeToCacheInBytes: 2 * 1024 * 1024,
    // An update takes over at once; the site's scripts are loaded when a page opens, so no
    // open page depends on a file the update removes.
    skipWaiting: true,
    clientsClaim: true,
    // One file: no workbox-*.js next to it to deploy and keep in step.
    inlineWorkboxRuntime: true,
    navigateFallbackDenylist: [/^\/admin\//, /^\/audio\//],
    runtimeCaching: [
      {
        urlPattern: /\/_astro\/.+\.(?:webp|avif|png|jpe?g|svg)$/,
        handler: 'StaleWhileRevalidate',
        options: {
          cacheName: 'images',
          expiration: { maxEntries: MAX_CACHED_IMAGES },
        },
      },
      {
        urlPattern: /\/_astro\/.+\.(?:woff2?|ttf)$/,
        handler: 'CacheFirst',
        options: { cacheName: 'fonts', expiration: { maxEntries: 30 } },
      },
    ],
  };
}
